#### 面试题 05.01. 插入
(https://leetcode.cn/problems/insert-into-bits-lcci/)
```cpp
// 分成三段然后组合 38.29
class Solution {
  public:
	int insertBits(int N, int M, int i, int j) {
		int front = 0, tail = 0;
		if(j == 31 && i == 0) {
			return M;
        }
        else if (j == 31 && i != 0) {
			// tail = (N << (32 - i)) >> (32 - i);
			tail = N & ((1 << i) - 1);
			return (M << i) + tail;
		} else if(j != 31 && i == 0) {
			front = (N >> (j + 1)) << (j + 1);
			return front + M;
		} else {
			front = (N >> (j + 1)) << (j + 1);
			// tail = (N << (32 - i)) >> (32 - i);
			tail  = N & ((1 << i) - 1);
			return front + tail + (M << i);
		}
		return 0;
	}
};
```
- 如果使用注释部分内容那么使用之前要保留一个 N 的备份，否则前面的修改正确，后面再用**失真的数据**结果出错
还可以使用位掩码：
```cpp
class Solution {
  public:
	int insertBits(int N, int M, int i, int j) {
		// 1. 创建掩码：将 i~j 位清零
		int mask = 0;
		for(int k = i; k <= j; k++) {
			mask |= (1 << k);
		}
		mask = ~mask;  // 取反，用于清零 i~j 位

		// 2. 清零 N 的 i~j 位
		N &= mask;

		// 3. 将 M 左移 i 位后与 N 合并
		M <<= i;
		return N | M;
	}
};
```
使用更优雅的解法，用法参考[[用法导向知识#位运算#其他操作技巧]]
```cpp
class Solution {
  public:
	int insertBits(int N, int M, int i, int j) {
		// 清除 N 中 i~j 位的值
		for(int k = i; k <= j; k++) {
			if(N & (1 << k)) {	// 如果第 k 位是 1
				N -= (1 << k);	// 清除该位
			}
		}

		// 插入 M
		return N | (M << i);
	}
};
```
#### 2154. 将找到的值乘以 2
(https://leetcode.cn/problems/keep-multiplying-found-values-by-two/)
简单枚举遍历方法不谈了，使用**只记录所有可能值**的方法
```cpp
class Solution {
public:
    int findFinalValue(vector<int>& nums, int original) {
        unordered_set<int> st;
        for (int x : nums) {
            int k = x / original;
            // 满足 x % original == 0 x是original的整数倍并且 倍数是2的k次方
            // 即 x * original == 2 ^ k
            if (x % original == 0 && (k & (k - 1)) == 0) {
                st.insert(x);
            }
        }
		// 最终还是要逐个检查
        while (st.contains(original)) {
            original *= 2;
        }
        return original;
    }
};
```
- 可以利用特性：[[用法导向知识#位运算#基本位操作技巧]]中，`X & (x - 1)` 会将最后一个 1->0，但是又因为判断条件 `(k & (k - 1)) == 0` 说明了原 `(k & (k - 1))` 结果中只有一个 1
```cpp
class Solution {
public:
    int findFinalValue(vector<int>& nums, int original) {
        int mask = 0;
        for (int x : nums) {
            int k = x / original;
            if (x % original == 0 && (k & (k - 1)) == 0) {
                mask |= k;
            }
        }

        // 找最低的 0，等价于取反后，找最低的 1（lowbit）
        mask = ~mask;
        return original * (mask & -mask);
    }
};
```
- 如果没有进入 if 条件那么这个数字就不符合题意，不是要选择出来的数直接跳过
- 这个 1 的位置很特殊，nums 中其他同时满足 `x * original == 2 ^ k` 的元素经过计算后 1 的位置是一样的，所以不会被重复计算到
- 那么每一个 1 的位置就可以被记录到一个 int 类型的一个位中
- 接下来就是要寻找到从右开始，第一个 0 的位置（这个位置就是**题目过程中**终止发生的位置）
- 通过取反后 `x & ~x` 找到最低位 1，只保留这个位置其他全变为 0，与 original 相乘得到结果
