最大的难点在于想不到使用枚举方法暴力求解
```cpp
struct Guess {
	Guess(array<int, 4> d, array<int, 10> dc, int rc, int rp)
		: digits(move(d))
		, digit_counts(move(dc))
		, right_counts(rc)
		, right_positions(rp) {}
	array<int, 4>  digits;
	array<int, 10> digit_counts;
	int			   right_counts;
	int			   right_positions;
};

array<int, 4> get4digits(int num) {
	array<int, 4> digits;
	for(int i = 3; i >= 0; i--) {
		digits[i] = num % 10;
		num /= 10;
	}
	return digits;
}

array<int, 10> get_digit_counts(int num) {
	array<int, 10> counts = { 0 };
	for(int i = 0; i < 4; i++) {
		int digit = num % 10;
		counts[digit]++;
		num /= 10;
	}
	return counts;
}

using Figure = Guess;

bool is_comfort(Figure& f, Guess& g) {
	int equal_sum = 0;
	for(int i = 0; i <= 9; i++) {
		int min_one = min(f.digit_counts[i], g.digit_counts[i]);
		equal_sum += min_one;
	}
	int equal_pos = 0;
	for(int i = 3; i >= 0; i--) {
		if(f.digits[i] == g.digits[i]) {
			equal_pos++;
		}
	}
	return equal_sum == g.right_counts && equal_pos == g.right_positions;
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	int n;
	while(cin >> n && n != 0) {
		int			  number, right_count, right_pos, candidate_num = 0, candidate;
		vector<Guess> guesses;
		guesses.reserve(n);
		for(int i = 0; i < n; i++) {
			cin >> number >> right_count >> right_pos;
			guesses.emplace_back(move(get4digits(number)), move(get_digit_counts(number)), right_count, right_pos);
		}
		for(int secret = 1000; secret <= 9999; secret++) {
			bool	   have_found_ans = true;
			const auto digits		  = get4digits(secret);
			const auto digit_counts	  = get_digit_counts(secret);
			Figure	   f(digits, digit_counts, 0, 0);
			for(auto& g : guesses) {
				if(!is_comfort(f, g)) {
					have_found_ans = false;
					break;
				}
			}
			if(have_found_ans == true) {
				candidate_num++;
				candidate = secret;
			}
		}
		if(candidate_num == 1) {
			cout << candidate << '\n';
		} else {
			cout << "Not sure\n";
		}
	}
	return 0;
}
```
> [!Demonstration]
> 使用严格证明
> 我们要证明：
> 若程序输出一个四位整数，则该整数满足所有给出的问答；
> 若程序输出 “Not sure”，则不存在唯一满足所有问答的四位整数。
> **引理 1（对单个 Guess 的判定）**
> 给定 secret S 与一次询问 (A,B,C)，程序按照上述公式计算得到的 exact 正好是 C，common 正好是 B，当且仅当 S 满足该条问答。
> 证明：
> exact 逐位比较，恰好统计了位置相同且数值相同的位数，这正是题目中 “C 个在正确的位置上”。
> common 对每个数字 d 取 `min(cntS[d],cntG[d])`，正好是 “猜对了 B 个数字” 的定义（数值相同且不计位置，重复出现按出现次数的较小者计）
> **引理 2（对整个对话的判定）**
> 一个四位整数 S 被程序认定为合法候选，当且仅当它满足所有 N 条问答。
> 证明：
> 程序依次遍历所有 Guess，对每个 Guess 按引理 1 检查 exact==C 与 common==B。只有全部通过，ok 才保持为 true，此时 S 被记录为候选。于是候选集合恰好是满足全部问答的 secret 集合。
> 引理 3（唯一性判定）
> 若候选集合中只有唯一的整数 X，程序输出 X；否则输出 “Not sure”。
> 证明：
> 在遍历所有 secret 的过程中，程序用计数器 candidateCnt 统计合法候选的个数。
> 若计数为 1，记录下的 answer 正是唯一的 X，随后输出 answer。
> 若计数不等于 1（即 0 或 ≥2），程序输出 “Not sure”。
> **定理（整体正确性）**
> 设 S* 为题目中真实可能的四位秘密数（若不存在记为不存在）。
> 若 S* 存在，依据题目给出的对话，所有 Guess 都被 S* 满足。根据引理 2，S* 必在程序的候选集合中。
> 若唯一，则候选集合大小为 1，依据引理 3 程序输出 S*。
> 若不唯一，候选集合大小 ≥2，依据引理 3 程序输出 “Not sure”。
> 若 S* 不存在，则候选集合为空，程序同样输出 “Not sure”。
> 因此无论真实情况如何，程序的输出都恰当地对应了题目要求。
> 复杂度分析
> 候选 secret 的数目：9999‑1000+1 = 9000。
> 对每个 secret，需要计算 `cntS[10]`（10 次）并对每个 Guess（最多 100）计算 common（10 次）以及 4 次位置比较。
> 总操作次数约为
> `9000 × (10 + 100×(10+4))  < 9×10⁶`
> 完全在毫秒级。空间上仅保存 Guess（≤100 条），几 KB。
