vector<string> generateAllDates(int year) {
    vector<string> dates;
    int monthDays[12] = { 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 };
    // 判断闰年（能被4整除但不能被100整除，或能被400整除）
    bool isLeap = (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
    if (isLeap) monthDays[1] = 29;
    for (int month = 1; month <= 12; ++month) {
        for (int day = 1; day <= monthDays[month - 1]; ++day) {
            ostringstream oss;
            oss << year
                << setw(2) << setfill('0') << month
                << setw(2) << setfill('0') << day;
            dates.push_back(oss.str());
        }
    }
    return dates;
}
int getCount() {
    int count = 0;
    for (int i = 2001; i <= 2021;i++) {
        vector<string> dates = generateAllDates(i);
        for (string& x : dates) {
            int sum = accumulate(x.begin(), x.end(), 0, [&](int acc, char& y) {
                return acc + (y - '0');
                });
            int res = sqrt(sum);
            if (res * res == sum) count++;
        }
    }
    return count;
}
int main() {
    cout << getCount();
}
