(https://leetcode.cn/problems/remove-element/) 简单模拟
```cpp
class Solution {
public:
    int removeElement(vector<int>& nums, int val) {
        int i = 0, j = 0, n = nums.size();
        while(i<n){
            nums[i] ^ val == 1 ? nums[j++] = nums[i] : i++;
