// B3693 数列前缀和 4 // 2026-04-22 00:13:05 // 2026-04-22 00:49:31 38 min
using u64 = unsigned long long;

// 模板代码
class NumMatrix {
	vector<vector<u64>> sum;
  public:
	NumMatrix(vector<vector<u64>>& matrix) {
		int m = matrix.size();
		int n = m == 0 ? 0 : matrix[0].size();
		sum.resize(m + 1, vector<u64>(n + 1, 0));
		for(int i = 0; i < m; i++) {
			for(int j = 0; j < n; j++) {
				sum[i + 1][j + 1] = sum[i + 1][j] + sum[i][j + 1] - sum[i][j] + matrix[i][j];
			}
		}
	}
	u64 sumRegion(int r1, int c1, int r2, int c2) {
		return sum[r2 + 1][c2 + 1] - sum[r2 + 1][c1] - sum[r1][c2 + 1] + sum[r1][c1];
	}
};

int main() {
	int T;
	cin >> T;
	while(T--) {
		int n, m, q;
		cin >> n >> m >> q;
		vector<vector<u64>> matrix(n, vector<u64>(m));
		for(int i = 0; i < n; i++) {
			for(int j = 0; j < m; j++) {
				cin >> matrix[i][j];
			}
		}
		NumMatrix nm(matrix);
		u64 xorSum = 0;
		while(q--) {
			int u, v, x, y;
			cin >> u >> v >> x >> y;
			// 转换为 0-indexed（因为类内部用 0-indexed 计算）
			u--;
			v--;
			x--;
			y--;
			u64 ans = nm.sumRegion(u, v, x, y);
			xorSum ^= ans;
		}
		cout << xorSum << '\n';
	}
	return 0;
}
```
- 题目中要求计算结果对 2 的 64 次方取余（注意 `2e64` 表示 `2*10^64`）
- ull 的最大值+1 刚好是取余的大小，所以**不用取余**，ull 的一旦溢出之后的数字就等于取余后的结果（注意**一定要 ull**才会不会有符号变化问题）
### 前缀和与哈希表
#### 930\. 和相同的二元子数组
(https://leetcode.cn/problems/binary-subarrays-with-sum/) 基本思路和 [[#560. 和为 K 的子数组]]一致，但由于测试集中数字由单调性，可以使用 [[#560. 和为 K 的子数组|560]] 一样的代码，也可以使用滑动窗口
-   双指针滑动窗口，利用单调性，前缀和一定是**递增的**
-   将元素放入窗口容器中，如果窗口内元素和 `<goal` 则继续放入
-   如果 `>goal` （1），则记录当前下标，再统计一次 `>=goal`（2） 的情况
-   （2）情况 - （1）情况数就是 `==goal` 的情况
```cpp
class Solution {
    public:
    int numSubarraysWithSum(vector<int>& nums, int goal) {
        int n = nums.size();
        int ans = 0;
        for (int r = 0, l1 = 0, l2 = 0, s1 = 0, s2 = 0; r < n; r++) {
            s1 += nums[r];
            s2 += nums[r];
            while (l1 <= r && s1 > goal) s1 -= nums[l1++];
            while (l2 <= r && s2 >= goal) s2 -= nums[l2++];
            ans += l2 - l1;
        }
        return ans;
    }
};
```
#### 560\. 和为 K 的子数组
(https://leetcode.cn/problems/subarray-sum-equals-k/) 本质上是枚举+前缀和方法，设前缀和为 pre\_sum，则 `pre_sum[i] - pre_sum[j] == k` 由于 i>j，所以将 i 作为枚举对象，通过先检索后更新的方法 需要注意到，数组中数字有正有负，如果数组满足某种单调性，则可以考虑[[题型分类#滑动窗口|滑动窗口解法]]，如 [[#930. 和相同的二元子数组]]
```cpp
class Solution{
public:
	int subuarraySum(vector<int>& nums, int k) {
		int n = nums.size(), count = 0;
		unordered_map<int, int> mapping;
		vector<int> pre_sum(n+1,0);
		mapping[0] = 1;
		for(int i = 1; i < n; i++){
			pre_sum[i+1] = pre_sum[i] + nums[i];
			if(mapping.find(pre_sum[i] - k)!=mapping.end()){
				count += mapping[pre_sum[i] - k];
			}
			mapping[pre_sum[i]]++;
		}
		return count;
	}
}
```
前缀和数组中只有新旧两个数字被使用，所以不需要用数组
```cpp
class Solution{
public:
	int subarraySum(vector<int>& nums, int k) {
        int n = nums.size(), count = 0, sum = 0;
        unordered_map<int, int> mapping = {{0,1}};
		for(int elem : nums){
            sum += elem;
            if (mapping.count(sum - k)){
                count += mapping[sum - k];
            }
            mapping[sum]++;
        }
		return count;
	}
};
```
-   和 [[#974. 和可被 K 整除的子数组]] 同样需要注意的是用哈希表作为前缀和匹配容器时，要注意初始化，例如输入 `[1,1,0]`，k = 2 如果没有这行代码，则会返回 0, 漏掉了 `1+1=2`，和 `1+1+0=2` 的情况，（**前缀和为 0 是特殊的统计计数情况**）
-   判断一个键值是否存在于哈希表中，用 `count` 不如 `find`，用 `find` 不如用 `contains`，find 多了一个构造*指向所找到元素的迭代器*这一步，其他在性能上与 `contain` 无异
