class Solution {
public:
    bool isHappy(int n) {
        for (int i = 0; i < 10;i++){
            int sum = 0;
            while(n>0){
                int temp = n % 10;
                sum += temp * temp;
                n /= 10;
            }
            n = sum;
        }
        return n == 1;
    }
};
