```cpp
-------------队列---------------------
class Solution {
    public:
    int findBottomLeftValue(TreeNode* root) {
        queue<TreeNode*> que;
        TreeNode* node;
        que.push(root);
        while (!que.empty()) {
            node = que.front();
            que.pop();
            if (node->right) que.push(node->right);
            if (node->left) que.push(node->left);
        }
        return node->val;
    }
};
-------------BFS双数组方法-------------
class Solution {
    public:
    int findBottomLeftValue(TreeNode* root) {
        if (root == NULL) return 0;
        vector<TreeNode*> cur = { root }, next;
        int left = 0;
        while (!cur.empty()) {
            left = cur[0]->val;
            for (auto node : cur) {
                if (node->left) next.push_back(node->left);
                if (node->right) next.push_back(node->right);
            }
            cur = next;
            next.clear();
        }
        return left;
    }
};
```
