#### P1443 马的遍历
https://www.luogu.com.cn/problem/P1443
```cpp
int n, m;
struct point { 	int x, y; };
bool is_outside(int x, int y) { return x < 0 || x > n - 1 || y < 0 || y > m - 1; }

void bfs(int x, int y, vector<vector<int>>& record) {
	int			 step		 = 1;
	int			 have_record = 0;
	vector<int>	 x_range	 = { -2, -1, 1, 2 };
	vector<int>	 y_range	 = { -2, -1, 1, 2 };
	deque<point> cur, next;

	cur.emplace_back(x, y);
	record[x][y] = 0;

	while(!cur.empty()) {
		while(!cur.empty()) {
			point p = cur.front();
			for(int xi : x_range) {
				for(int yi : y_range) {
					if(abs(xi) != abs(yi)) {
						int x_new = p.x + xi;
						int y_new = p.y + yi;
						if(!is_outside(x_new, y_new) && record[x_new][y_new] == -1) {
							next.emplace_back(x_new, y_new);
							record[x_new][y_new] = step;
							have_record++;
						}
					}
				}
			}
			cur.pop_front();
		}
		if(have_record == n * m - 1) {
			break;
		}
		cur = next;
		next.clear();
		step++;
	}
}

int main() {
	int x, y;
	cin >> n >> m >> x >> y;
	x--;
	y--;
	vector<vector<int>> records(n, vector<int>(m, -1));
	bfs(x, y, records);
	for(auto& lines : records) {
		for(auto& item : lines) {
			cout << item << " ";
		}
		cout << "\n";
	}
	return 0;
}
```
