```cpp
class Solution {
    void dfs(int x, int y, vector<vector<char>>& grid) {
        if (x >= n || x < 0 || y >= m || y < 0 || visit[x][y] || grid[x][y] == '0')
            return;
        visit[x][y] = true;
        dfs(x + 1, y, grid);
        dfs(x - 1, y, grid);
        dfs(x, y + 1, grid);
        dfs(x, y - 1, grid);
    }
    int n, m;
    vector<vector<bool>> visit;
   public:
    int numIslands(vector<vector<char>>& grid) {
        n = grid.size();
        if (n == 0)
            return 0;
        m = grid[0].size();
        visit.resize(n, vector<bool>(m, false));
        int count = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (visit[i][j])
                    continue;
                if (visit[i][j] == false && grid[i][j] == '1') {
                    dfs(i, j, grid);
                    count++;
                }
            }
        }
        return count;
    }
};
