- 这一解法出现的问题有:
	- record 中没有记录两种状态，有些路线经过某一个格子时是可以使用魔法的（从相邻原本有色格子），有些不行（从灰色格子），刚好经过一个格子也只有有魔法和无魔法两种状态，需三维数组
	- 根据有无魔法可以剪枝。错误版本是先进入一个格子（先将 record 和之前的 cost 相比较，这里的 record 中存储的也是**进入格子之前花费的总额**，这样并不直观也容易出错）。应该***进入一个格子之后就记录开销并比较***，超过了之前记录的值，说明同一位置已有更优解->剪枝
	- 走进无色格子之后，下一步如果还能走，那么这个无色格子颜色就应该变化为**上一步格子相同颜色**，这是最优解，**下一步的previous_color 就应该传入这一步的 previous_color**
```cpp
int M;     // 0-indexed 的最大坐标（= 原 m - 1）
int ans;   // 最终答案

bool is_outside(int x, int y) {
    if (0 <= x && x <= M && 0 <= y && y <= M)
        return false;
    return true;
}

void dfs(int                          x,
         int                          y,
         vector<vector<int>>&         matrix,
         vector<vector<array<int, 2>>>& record,  // [x][y][0]=不能施法, [1]=能施法
         int                          prev_color,
         int                          cost,
         bool                         magic_ok) {

    if (is_outside(x, y)) return;
    if (matrix[x][y] == 2 && !magic_ok) return;

    // ---- 计算进入花费（移到 record 检查之前，修复错误 3） ----
    bool next_magic;
    if (prev_color == -100) {
        // 起点，无花费
        next_magic = true;
    } else if (matrix[x][y] == 2) {
        // 用魔法进入无色格子，花费 2
        cost += 2;
        next_magic = false;
    } else if (matrix[x][y] != prev_color) {
        // 不同颜色，花费 1
        cost += 1;
        next_magic = true;
    } else {
        // 相同颜色，花费 0
        next_magic = true;
    }

    // ---- 三维剪枝（修复错误 2） ----
    int idx = next_magic ? 1 : 0;
    if (cost >= record[x][y][idx]) return;
    record[x][y][idx] = cost;

    // ---- 到达终点 ----
    if (x == M && y == M) {
        ans = min(ans, cost);
        return;
    }

    // ---- 当前格子的有效颜色（修复错误 1） ----
    // 若站在魔法格子上，颜色 = 来向颜色（最优选择）
    // 若站在自然有色的格子上，颜色 = matrix[x][y]
    int eff_color = (matrix[x][y] == 2) ? prev_color : matrix[x][y];

	// 往回走的路径会在判断 cost >= record[x][y][idx] 被剪断
    dfs(x - 1, y, matrix, record, eff_color, cost, next_magic);
    dfs(x + 1, y, matrix, record, eff_color, cost, next_magic);
    dfs(x, y - 1, matrix, record, eff_color, cost, next_magic);
    dfs(x, y + 1, matrix, record, eff_color, cost, next_magic);
}

int solve() {
    M   = m - 1;   // m 是全局的原始尺寸，转为 0-indexed 上界
    ans = INT_MAX;

    // 转为 vector（保留你原代码的风格）
    vector<vector<int>> mat(m, vector<int>(m));
    for (int i = 0; i < m; ++i)
        for (int j = 0; j < m; ++j)
            mat[i][j] = board[i][j];

    // record[x][y][0] = magic_available==false 时的最小花费
    // record[x][y][1] = magic_available==true  时的最小花费
    vector<vector<array<int, 2>>> rec(m, vector<array<int, 2>>(m, {INT_MAX, INT_MAX}));

    dfs(0, 0, mat, rec, -100, 0, true);
    return ans == INT_MAX ? -1 : ans;
}
```
