(https://leetcode.cn/problems/find-subsequence-of-length-k-with-the-largest-sum/)
前 k 大元素类型题目的变体，参考 [[#215. 数组中的第K个最大元素]]
正常的写法：
```cpp
class Solution {
public:
    vector<int> maxSubsequence(vector<int>& nums, int k) {
        // 使用最小堆存储值及其索引
        priority_queue<pair<int, int>, vector<pair<int, int>>, greater<>> pq;

        for (int i = 0; i < nums.size(); i++) {
            if (pq.size() < k) {
                pq.emplace(nums[i], i);
            } else if (nums[i] > pq.top().first) {
                pq.pop();
                pq.emplace(nums[i], i);
            }
        }
        vector<pair<int, int>> temp;
        while (!pq.empty()) {
            temp.push_back(pq.top());
            pq.pop();
        }

        sort(temp.begin(), temp.end(), [](auto& a, auto& b) {
            return a.second < b.second;
        });
        vector<int> result;
        for (auto& [val, idx] : temp) {
            result.push_back(val);
        }

        return result;
    }
};
```
冗余代码非常多，这里可以使用稳定排序实现
```cpp
class Solution {
public:
    vector<int> maxSubsequence(vector<int>& nums, int k) {
        vector<int> idx(nums.size());
        iota(idx.begin(), idx.end(), 0);

        partial_sort(idx.begin(), idx.begin() + k, idx.end(),
                     [&](int i, int j) { return nums[i] > nums[j]; }); // 找到最大的k个元素，这些元素从大到小排序，并将它们的索引放在idx的前k个位置（idx中存储索引）
        sort(idx.begin(), idx.begin() + k); // 按照下标排序，这样让idx中最大的几个元素按照索引排序
        vector<int> result;
        for (int i = 0; i < k; i++) {
            result.push_back(nums[idx[i]]); // 根据索引值填入答案中
        }

        return result;
    }
};
```
