class Solution {
public:
    string removeStars(string s) {
        int n = s.size(), slow = 0;
        string out;
        for (int fast = 0; fast < n; fast++) {
            if (s[fast] == '*') {
                if (!out.empty()) out.pop_back();
                slow = fast + 1;
            }
            else {
                out.append(1, s[slow++]);
            }
        }
        return out;
    }
};
