class Solution {
public:
    int dfs(int n, vector<int>& memo) {
        if (n <= 1) return 1;
        if (memo[n] != -1) return memo[n];
        return memo[n] = dfs(n - 1, memo) + dfs(n - 2, memo);
    }
    int climbStairs(int n) {
        vector<int> memo(n + 1, -1);
        return dfs(n, memo);
    }
};
// 将递归改为迭代，其实就是将状态转移方程写入循环中
class Solution {
    public:
    int climbStairs(int n) {
        vector<int> dp(n + 1);
        dp[0] = 1;
        dp[1] = 1;
        for (int i = 2; i < n; i++) {
            dp[i] = dp[i - 1] + dp[i - 2];
        }
        return dp[n];
    }
};
// 状态压缩
class Solution {
public:
    int climbStairs(int n) {
        int pre = 1, cur = 1, ans = 0;
        for (int i = 2; i <= n; i++) {
            ans = pre + cur;
            cur = pre;
            pre = ans;
        }
        return ans;
    }
};
