动态规划版本
```cpp
class Solution {
    const int mod = 1e9 + 7;
public:
    int countGoodStrings(int low, int high, int zero, int one) {
        vector<int> dp(high + 1, 0);
        dp[0] = 1;
        for (int i = 1; i <= high; i++) {
            if (i >= zero)
                dp[i] += dp[i - zero];
            if (i >= one)
                dp[i] += dp[i - one];
        }
        int count = 0;
        for (auto& x: dp ) {
            count = (count + x) % mod;
        }
        return count;
    }
};
```
