```cpp
class Solution {
public:
    string change(int big, string bigChar, int small, string smallChar) {
        string output;
        while (big - small > 2) {
            big -= 2;
            output += bigChar + bigChar;
            small -= 1;
            output += smallChar;
        }
        while (big > 0 || small > 0) {
            if (big != 0) {
                big--;
                output += bigChar;
            }
            if (small != 0) {
                small--;
                output += smallChar;
            }
        }
        return output;
    }
    string strWithout3a3b(int a, int b) {
        return a > b ? change(a, "a", b, "b") : change(b, "b", a, "a");
    }
};
