struct VectorHash {
	size_t operator()(const vector<int>& other) const {
		size_t seed = 0;
		for(int i = 0; i < other.size(); i++) {
			seed ^= (std::hash<int>{}(other[i]) << i);
		}
		return seed;
	}
};

class Solution {
	using Records = unordered_set<vector<int>, VectorHash>;

	Records records;

	void traceback(vector<int>& nums, vector<int>& path, int startIndex) {
		for(int i = startIndex; i < nums.size(); i++) {
			if((i > startIndex) && (nums[i] == nums[i - 1])) {
				continue;
			}
			path.emplace_back(nums[i]);
			records.insert(path);
			traceback(nums, path, i + 1);
			path.pop_back();
		}
	}

  public:
	vector<vector<int>> subsetsWithDup(vector<int>& nums) {
		sort(nums.begin(), nums.end());
        vector<int> path;
		traceback(nums, path, 0);
		vector<vector<int>> result(records.begin(), records.end());
        result.insert({});
		return result;
	}
};
```
